"""Small dependency-free TOML reader for the application's configuration files."""
import re, json, ast

def split_top(text,sep=','):
    out=[]; start=0; level=0; quote=None; escape=False
    for i,c in enumerate(text):
        if quote:
            if escape: escape=False
            elif c=='\\' and quote=='"': escape=True
            elif c==quote: quote=None
        elif c in '\"\'': quote=c
        elif c in '[{(': level+=1
        elif c in ']})': level-=1
        elif c==sep and level==0: out.append(text[start:i].strip());start=i+1
    out.append(text[start:].strip())
    return out

def value(s):
    s=s.strip()
    if s in ('true','false'): return s=='true'
    if s.startswith('[') and s.endswith(']'): return [value(x) for x in split_top(s[1:-1]) if x]
    if s.startswith('{') and s.endswith('}'):
        return {unquote(k.strip()):value(v) for x in split_top(s[1:-1]) if x for k,v in [x.split('=',1)]}
    if s.startswith(('"',"'")):
        try: return json.loads(s) if s[0]=='"' else s[1:-1]
        except: return ast.literal_eval(s)
    try: return int(s.replace('_',''),0)
    except:
        try: return int(s.replace('_',''))
        except:
            try: return float(s)
            except: raise ValueError('invalid value '+s)

def unquote(s):return s[1:-1] if len(s)>1 and s[0] in '\"\'' and s[-1]==s[0] else s

def loads(text):
    result={}; table=result; buf=''
    for line in text.splitlines():
        quote=None; esc=False; end=len(line)
        for i,c in enumerate(line):
            if quote:
                if esc:esc=False
                elif c=='\\' and quote=='"':esc=True
                elif c==quote:quote=None
            elif c in '\"\'':quote=c
            elif c=='#':end=i;break
        line=line[:end].strip()
        if not line:continue
        buf+=(('\n' if buf else '')+line)
        if buf.startswith('[') and '=' not in buf and buf.endswith(']'):
            keys=split_top(buf.strip('[]'),'.'); table=result
            for k in keys:table=table.setdefault(unquote(k),{})
            buf='';continue
        if '=' not in buf:raise ValueError('expected an equals sign')
        k,v=buf.split('=',1)
        if v.count('[')>v.count(']') or v.count('{')>v.count('}'):continue
        val=value(v); keys=split_top(k.strip(),'.'); t=table
        for key in keys[:-1]:t=t.setdefault(unquote(key),{})
        t[unquote(keys[-1])]=val;buf=''
    if buf:raise ValueError('unfinished value')
    return result

def dumps_val(v):
    if v is True:return 'true'
    if v is False:return 'false'
    if isinstance(v,str):return json.dumps(v,ensure_ascii=False)
    if isinstance(v,list):return '['+', '.join(dumps_val(x) for x in v)+']'
    if isinstance(v,dict):return '{ '+', '.join(k+' = '+dumps_val(x) for k,x in v.items())+' }'
    return str(v)
