def dumps_val(v):
    if v is True:return 'true'
    if v is False:return 'false'
    if isinstance(v,str):return json.dumps(v,ensure_ascii=False)
    if isinstance(v,list):return '['+', '.join(dumps_val(x) for x in v)+']'
    if isinstance(v,dict):return '{ '+', '.join(k+' = '+dumps_val(x) for k,x in v.items())+' }'
    return str(v)
