def make_diff(a,b,file):
    lines=list(difflib.unified_diff(a.splitlines(True),b.splitlines(True),fromfile=file,tofile=file+' (fixed)',n=3))
    if not lines:return ''
    # Adjacent old/new lines are interleaved in the terminal's unified view.
    out=[];i=0
    while i<len(lines):
        if lines[i].startswith('-') and not lines[i].startswith('---'):
            minus=[];plus=[]
            while i<len(lines) and lines[i].startswith('-'):minus.append(lines[i]);i+=1
            while i<len(lines) and lines[i].startswith('+'):plus.append(lines[i]);i+=1
            for j in range(max(len(minus),len(plus))):
                if j<len(minus):out.append(minus[j])
                if j<len(plus):out.append(plus[j])
        else:out.append(lines[i]);i+=1
    return ''.join(out)+'\n\n'
