        s='['+k+']\n'
        for x,y in v.items():
            if not isinstance(y,dict):s+=x+' = '+mini_toml.dumps_val(y)+'\n'
        s+='\n'
        for x,y in v.items():
            if isinstance(y,dict):s+=block(k+'.'+x,y)
        return s
    return ''.join(block(k,v) for k,v in cfg.items() if isinstance(v,dict))

def config_command(pos,opts):
    cfg,loaded,custom=config_load(opts)
    if pos and pos[0]=='file':
        out(str(loaded.resolve())+'\n' if loaded else 'No configuration file found (using defaults)\n');return 0
    if pos and pos[0]=='get':
        if len(pos)<2:err('error: the following required arguments were not provided:\n  <KEY>\n\nUsage: '+PROG+" config get <KEY>\n\nFor more information, try '--help'.");return 2
        key=pos[1]
        if '.' not in key:err('Key must be in the form global.key or MDxxx.key');return 2
        key=key.replace('_','-');section,field=key.split('.',1)
        if section.upper() in RULES:section=section.upper()
        if section not in cfg or field not in cfg[section]:err('Unknown config key: '+key);return 2
        source=str(loaded) if field in custom.get(section,{}) else 'default'
        out(section+'.'+field+' = '+mini_toml.dumps_val(cfg[section][field])+' [from '+source+']\n');return 0
    if opts.get('no-defaults'):
        cfg={k:v for k,v in cfg.items() if not k.startswith('MD') or k in custom}
    fmt=opts.get('output')
    if fmt=='json':out(json_text(cfg))
    elif fmt=='toml':out(toml_dump(cfg))
    elif opts.get('no-defaults') and not custom:out(data('empty_config_display.txt'))
    elif not custom:out(data('default_display.txt'))
    else:
        lines=[]
        for section,values in cfg.items():
            if section in ('per-file-ignores','per-file-flavor','code-block-tools') or not isinstance(values,dict):continue
            lines.append(('['+section+']',''))
            for k,v in values.items():
                val=mini_toml.dumps_val(v);src=str(loaded) if k in custom.get(section,{}) else 'default'
                if opts.get('no-defaults') and src=='default':continue
                lines.append((k+' = '+val,'[from '+src+']'))
            lines.append(('',''))
        width=max((len(a) for a,b in lines),default=0)+2
        out(''.join((a.ljust(width)+b if a else '')+'\n' for a,b in lines))
    return 0

def init_command(opts):
    if opts.get('pyproject'):
        p=pathlib.Path('pyproject.toml');template=data('init_pyproject_toml.txt')
        if p.exists():
            old=p.read_text()
            if '[tool.rumdl' in old:err('Error: Failed to create config file: rumdl configuration already exists in pyproject.toml');return 2
            p.write_text(old.rstrip()+'\n\n'+template);out('Added rumdl configuration to pyproject.toml\n')
        else:p.write_text(template);out('Created pyproject.toml with rumdl configuration\n')
    else:
        p=pathlib.Path(opts.get('config','.rumdl.toml'))
        if p.exists():err('Error: Failed to create config file: Configuration file already exists at '+str(p));return 2
        p.write_text(data('init__rumdl_toml.txt'))
        out('Created default configuration file: '+str(p)+'\n\nSetup complete! You can now:\n  • Run rumdl check . to lint your Markdown files\n  • Open your editor to see real-time linting\n')
    return 0

def import_command(pos,opts):
    if not pos:err('error: the following required arguments were not provided:\n  <FILE>\n\nUsage: '+PROG+" import [OPTIONS] <FILE>\n\nFor more information, try '--help'.");return 2
    try:
        raw=pathlib.Path(pos[0]).read_text();raw=re.sub(r'^\s*//.*$','',raw,flags=re.M);d=json.loads(raw)
    except Exception as e:err(f'Error: Failed to import configuration: {e}');return 2
    cfg={'global':{}};disable=[];enable=[]
    for k,v in d.items():
        if k=='default':continue
        r=engine.rule_id(k)
        if r not in RULES:continue
        if v is False:disable.append(r)
        elif v is True:enable.append(r)
        elif isinstance(v,dict):cfg[r]=normalize(v)
    if d.get('default') is False:cfg['global']['enable']=enable+list(cfg.keys())[1:]
    if disable:cfg['global']['disable']=disable
    text=json_text(cfg) if opts.get('format')=='json' else toml_dump(cfg)
    if opts.get('dry-run'):out(text)
    else:
        path=opts.get('output','.rumdl.toml');pathlib.Path(path).write_text(text);out('Configuration written to '+path+'\n')
    return 0

def main():
    cmd,pos,opts=parse(sys.argv[1:])
    if cmd in ('check','fmt'):return check_command(cmd,pos,opts)
    if cmd=='version':out('rumdl 0.1.13\n');return 0
    if cmd=='rule':return rule_command(pos,opts)
    if cmd=='explain':
        if not pos:err('error: the following required arguments were not provided:\n  <RULE>\n\nUsage: '+PROG+" explain [OPTIONS] <RULE>\n\nFor more information, try '--help'.");return 2
        r=engine.rule_id(pos[0])
        if r not in RULES:err(f"Rule '{pos[0]}' not found.");return 2
        try:out(json.loads(data('explanations.json'))[r])
        except:out(r+' - '+RULES[r]['description']+'\n')
        return 0
    if cmd=='init':return init_command(opts)
    if cmd=='config':return config_command(pos,opts)
    if cmd=='import':return import_command(pos,opts)
    if cmd=='clean':
        cfg,_,_=config_load(opts);p=pathlib.Path(os.getenv('RUMDL_CACHE_DIR',cfg.get('global',{}).get('cache-dir','.rumdl_cache')))
        if p.exists():shutil.rmtree(p);out('Cache cleared successfully\n')
        else:out('No cache directory found\n')
        return 0
    if cmd=='schema':
        if pos and pos[0]=='print':out(data('schema.json'));return 0
        if pos and pos[0]=='generate':pathlib.Path('rumdl.schema.json').write_text(data('schema.json'));out('Schema generated successfully\n');return 0
        if pos and pos[0]=='check':return 0
        out(helptext('schema'));return 2
    if cmd=='completions':return 0
    if cmd=='server':return server()
    if cmd=='vscode':err('Error: VS Code is not installed or not in PATH');return 1
    return 0

def server():
    while True:
        line=sys.stdin.buffer.readline()
        if not line:return 0
        m=re.match(rb'Content-Length: (\d+)',line,re.I)
        if not m:continue
        length=int(m[1]);sys.stdin.buffer.readline()
        try:msg=json.loads(sys.stdin.buffer.read(length))
        except:return 0
        if msg.get('method')=='exit':return 0
        if 'id' not in msg:continue
        result=None
        if msg.get('method')=='initialize':result={'capabilities':{'textDocumentSync':1,'documentFormattingProvider':True},'serverInfo':{'name':'rumdl','version':'0.1.13'}}
        reply=json.dumps({'jsonrpc':'2.0','id':msg['id'],'result':result},separators=(',',':')).encode()
        sys.stdout.buffer.write(b'Content-Length: '+str(len(reply)).encode()+b'\r\n\r\n'+reply);sys.stdout.buffer.flush()

if __name__=='__main__':
    try:sys.exit(main())
    except BrokenPipeError:sys.exit(0)
